BEGIN TRY.examples.with-transaction.sql:
CREATE TABLE #Loan (LoanId int PRIMARY KEY);
BEGIN TRY
    BEGIN TRAN;
    INSERT INTO #Loan VALUES (1);
    INSERT INTO #Loan VALUES (1);   -- Duplicate key, jumps to CATCH
    COMMIT;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK;    -- End the transaction before handling the error
    SELECT ERROR_NUMBER() AS Num, ERROR_MESSAGE() AS Msg;   -- Result: 2627
END CATCH;
SELECT COUNT(*) AS LoanCount FROM #Loan;   -- Result: 0, the first row was rolled back too
DROP TABLE #Loan;
GO

BEGIN TRANSACTION.examples.nested-trap.sql:
CREATE TABLE #Loan (LoanId int);
BEGIN TRAN;                          -- @@TRANCOUNT = 1
    INSERT INTO #Loan VALUES (1);
    BEGIN TRAN;                      -- @@TRANCOUNT = 2, not a separate transaction
        INSERT INTO #Loan VALUES (2);
    COMMIT;                          -- Only drops the count to 1; nothing is committed yet
ROLLBACK;                            -- Rolls back to the outermost: both rows are gone
SELECT COUNT(*) AS LoanCount FROM #Loan;   -- Result: 0
DROP TABLE #Loan;
GO

