BEGIN TRY
    BEGIN TRAN;
    SAVE TRAN Sp1;
    SELECT 1 / 0;
END TRY
BEGIN CATCH
    SELECT XACT_STATE() AS State;   -- Result: -1, the transaction is doomed
    ROLLBACK;                       -- Only a full rollback; ROLLBACK TRAN Sp1 raises 3931
END CATCH;
SET XACT_ABORT OFF;
GO

