DECLARE copy_cursor CURSOR LOCAL FAST_FORWARD FOR
    SELECT v.CopyNo FROM (VALUES (1), (2), (3)) AS v(CopyNo);
OPEN copy_cursor;
FETCH NEXT FROM copy_cursor INTO @CopyNo;
WHILE @@FETCH_STATUS = 0
BEGIN
