DECLARE c CURSOR LOCAL FAST_FORWARD FOR
    SELECT v.CopyNo FROM (VALUES (1), (2)) AS v(CopyNo);
OPEN c;
WHILE 1 = 1
BEGIN
    FETCH NEXT FROM c INTO @CopyNo;
    IF @@FETCH_STATUS <> 0 BREAK;   -- No need for a second FETCH before the loop
    PRINT @CopyNo;
END
CLOSE c;
DEALLOCATE c;
GO

