GRANT.examples.deny-wins.sql:
CREATE USER Lib_Reader WITHOUT LOGIN;
CREATE ROLE Lib_Staff;
ALTER ROLE Lib_Staff ADD MEMBER Lib_Reader;
GRANT SELECT ON SCHEMA::dbo TO Lib_Reader;   -- The user has a GRANT
DENY SELECT ON SCHEMA::dbo TO Lib_Staff;     -- Its role has a DENY
EXECUTE AS USER = 'Lib_Reader';
SELECT HAS_PERMS_BY_NAME('dbo', 'SCHEMA', 'SELECT') AS CanSelect;   -- Result: 0, DENY wins
REVERT;
ALTER ROLE Lib_Staff DROP MEMBER Lib_Reader;
DROP ROLE Lib_Staff;
DROP USER Lib_Reader;
GO

